import type { SagaId } from "./cards";

/**
 * Parte editoriale del database carte, scritta a mano da OriginsMeta e indicizzata per slug:
 * - `saga`: la leggenda da cui viene la carta (le "saghe" sono una classificazione nostra, il gioco non la espone);
 * - `origin`: una riga sull'origine del personaggio, in inglese e italiano;
 * - `it`: traduzione italiana del testo ufficiale della carta (l'inglese sta in `woo-cards.json`;
 *   le parole chiave del gioco restano in inglese, come nelle pill del sito).
 * Quando `npm run import:woo` segnala un testo cambiato, va aggiornata la riga `it` corrispondente.
 */
export type Lore = {
  saga: SagaId;
  origin?: { en: string; it: string };
  /**
   * Testo ufficiale inglese letto nel gioco, quando quello di World of Origins è rimasto indietro: vince su
   * `woo-cards.json`. Verifica carta per carta sulla Demo 2.0 del 22/09/2026 (collezione del gioco, 122 carte):
   * le statistiche coincidevano tutte, 16 testi no (effetti cambiati nelle patch 0.6.2/0.6.3 e formulazioni).
   */
  en?: string;
  it?: string;
  /** chiave ufficiale della carta quando World of Origins non la espone (letta dal materiale ufficiale Koin) */
  key?: string;
};

